/* Replay vectors are generated by the UNMODIFIED supplied C model.
 * Compile with: cc -std=c11 -Ireference tools/gen_msu_vectors.c
 *               reference/msu_model.c -o build/gen_msu_vectors
 * stdout = vectors; stderr = coverage summary.
 */
#include "msu_model.h"
#include <inttypes.h>
#include <limits.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define CHECK(x) do { if (!(x)) { \
    fprintf(stderr, "generator failure line %d: %s\n", __LINE__, #x); \
    exit(1); } } while (0)

static Msu q;
static unsigned cycle, phase;
static unsigned accepted, written, completed, simultaneous, faults, resets;
static unsigned stalled, full, full_last, full_bad, head_wraps, max_count;
static uint32_t rng = 7;

static uint32_t random32(void)
{
    rng = rng * UINT32_C(1664525) + UINT32_C(1013904223);
    return rng;
}

static void print_matrix(const TcMatrix32 *m)
{
    for (int r = 7; r >= 0; --r)
        for (int c = 7; c >= 0; --c)
            printf("%08" PRIx32, (uint32_t)m->v[r][c]);
}

static MsuEvents step(MsuInputs in, bool rst_n)
{
    MsuOutputs out;
    MsuEvents e = {0};
    Msu before;
    IoStatus status = IO_OK;
    if (!rst_n) { msu_reset(&q); ++resets; }
    msu_peek(&q, &out);
    before = q;
    if (rst_n) status = msu_tick(&q, &in, &e);
    CHECK(status == IO_OK || status == IO_BAD_FORMAT);
    if (status != IO_OK) {
        CHECK(memcmp(&q, &before, sizeof q) == 0);
        CHECK(!e.result_accepted && !e.beat_written && !e.tile_done);
        ++faults;
    }
    CHECK(q.count <= 2 && q.row < 8 && q.head < 2);
    CHECK(q.count != 0 || q.row == 0);
    if (q.count > max_count) max_count = q.count;
    accepted += e.result_accepted;
    written += e.beat_written;
    completed += e.tile_done;
    simultaneous += e.tile_done && e.result_accepted;
    stalled += rst_n && out.write_valid && !in.write_ready;
    full += rst_n && before.count == 2;
    full_last += rst_n && before.count == 2 && out.write_last && e.tile_done;
    full_bad += rst_n && before.count == 2 && in.result_valid &&
                (in.meta.dst_addr & 31u) != 0 && status == IO_OK;
    head_wraps += e.tile_done && before.head == 1 && q.head == 0;

    // The ready/valid columns contain RAW C peek outputs. The SV testbench
    // explicitly qualifies them with reset/status for the safe RTL interface.
    printf("%u %u %x %x %08" PRIx32 " %016" PRIx64 " ",
           cycle++, phase, rst_n, in.result_valid, in.meta.tile_id, in.meta.dst_addr);
    print_matrix(&in.result);
    printf(" %x %x %x %x %016" PRIx64 " ", in.write_ready,
           (unsigned)status, out.result_ready, out.write_valid, out.write_addr);
    for (int b = 31; b >= 0; --b) printf("%02x", out.write_data[b]);
    printf(" %x %08" PRIx32 " %016" PRIx64,
           out.write_last, out.write_meta.tile_id, out.write_meta.dst_addr);
    printf(" %x %x %x %08" PRIx32 " %016" PRIx64 " %x %x %x\n",
           e.result_accepted, e.beat_written, e.tile_done,
           e.completed.tile_id, e.completed.dst_addr, q.head, q.count, q.row);
    return e;
}

static void reset_model(void)
{
    MsuInputs in = {0};
    step(in, false);
    step(in, true);
}

static MsuInputs result_input(uint32_t id, uint64_t addr, bool ready)
{
    MsuInputs in = {0};
    in.result_valid = true;
    in.meta.tile_id = id;
    in.meta.dst_addr = addr;
    in.write_ready = ready;
    for (unsigned r = 0; r < 8; ++r)
        for (unsigned c = 0; c < 8; ++c) {
            uint32_t bits = random32();
            // memcpy retains every INT32 bit pattern without a narrowing cast.
            memcpy(&in.result.v[r][c], &bits, sizeof bits);
        }
    in.result.v[0][0] = INT32_MIN;
    in.result.v[0][1] = INT32_MAX;
    in.result.v[0][2] = -1;
    in.result.v[0][3] = 0;
    in.result.v[0][4] = 1;
    in.result.v[0][5] = INT32_C(0x01234567);
    return in;
}

static void drain(void)
{
    MsuInputs in = {0};
    in.write_ready = true;
    for (unsigned watchdog = 0; q.count; ++watchdog) {
        CHECK(watchdog < 17);
        step(in, true);
    }
    step(in, true);
}

static void original_120_test(void)
{
    enum { N = 120 };
    TcMatrix32 values[N];
    unsigned offered = 0, beats = 0, local_cycles = 0, sim = 0;
    phase = 1;
    rng = 7;
    for (unsigned t = 0; t < N; ++t)
        for (unsigned i = 0; i < 8; ++i)
            for (unsigned j = 0; j < 8; ++j)
                values[t].v[i][j] = i == 0 ? INT32_MIN : i == 1 ? INT32_MAX :
                    (int32_t)(random32() & UINT32_C(0x7fffffff)) * (j%2u ? -1 : 1);
    reset_model();
    for (; local_cycles < 20000 && beats < N*8u; ++local_cycles) {
        MsuInputs in = {0};
        MsuEvents e;
        in.result_valid = offered < N && (offered != 1 || local_cycles >= 8);
        in.meta.tile_id = offered;
        in.meta.dst_addr = (uint64_t)offered * 256u;
        if (in.result_valid) in.result = values[offered];
        in.write_ready = local_cycles < 10 ||
            (!(local_cycles >= 40 && local_cycles < 180) && local_cycles%5u != 2);
        e = step(in, true);
        offered += e.result_accepted;
        beats += e.beat_written;
        sim += e.tile_done && e.result_accepted;
    }
    CHECK(offered == N && beats == N*8u && q.count == 0 && sim != 0);
    fprintf(stderr, "original traffic: results=%u beats=%u cycles=%u simultaneous=%u\n",
            offered, beats, local_cycles, sim);
}

static void directed_tests(void)
{
    MsuInputs in;
    MsuEvents e;
    unsigned sim_before;
    phase = 2; // Full queue, old-state ready, then acceptance on the next edge.
    reset_model();
    step(result_input(200, UINT64_C(0x1234567800000000), false), true);
    step(result_input(201, UINT64_C(0x2000000040), false), true);
    in = result_input(202, UINT64_C(0x3000000080), true);
    for (unsigned r = 0; r < 8; ++r) {
        e = step(in, true);
        CHECK(!e.result_accepted && e.beat_written && e.tile_done == (r == 7));
    }
    e = step(in, true);
    CHECK(e.result_accepted && e.beat_written && q.count == 2);
    drain();

    phase = 3; // Deliberately obtain MANY simultaneous final-row/new-result edges.
    reset_model();
    sim_before = simultaneous;
    step(result_input(300, UINT64_C(0x4000), false), true);
    for (unsigned t = 0; t < 32; ++t) {
        memset(&in, 0, sizeof in);
        in.write_ready = true;
        for (unsigned r = 0; r < 7; ++r) step(in, true);
        in = result_input(301+t, UINT64_C(0x5000) + t*256u, true);
        e = step(in, true);
        CHECK(e.result_accepted && e.tile_done && q.count == 1 && q.row == 0);
    }
    CHECK(simultaneous - sim_before == 32);
    drain();

    phase = 4; // Address boundaries and whole-edge rejection.
    reset_model();
    for (unsigned low = 1; low < 32; ++low) {
        in = result_input(400+low, UINT64_C(0x1000)+low, true);
        e = step(in, true);
        CHECK(q.count == 0 && !e.result_accepted);
    }
    for (unsigned n = 1; n < 8; ++n) {
        in = result_input(440+n, UINT64_MAX - 255u + n*32u, true);
        step(in, true);
        CHECK(q.count == 0);
    }
    step(result_input(450, UINT64_MAX, true), true);
    in = result_input(451, UINT64_MAX-255u, false); // Last legal aligned base.
    CHECK(step(in, true).result_accepted);
    // An invalid input cancels even a simultaneous pending output write.
    in = result_input(452, UINT64_C(1), true);
    e = step(in, true);
    CHECK(!e.beat_written && q.row == 0 && q.count == 1);
    memset(&in, 0, sizeof in);
    in.write_ready = true;
    for (unsigned r = 0; r < 7; ++r) step(in, true);
    in = result_input(453, UINT64_C(0xffffffffffffffe0), true);
    e = step(in, true);
    CHECK(!e.tile_done && q.row == 7 && q.count == 1);
    in.meta.dst_addr = 0;
    e = step(in, true);
    CHECK(e.tile_done && e.result_accepted && e.completed.tile_id == 451);
    drain();
    // Bad metadata is not evaluated while full, just like C.
    step(result_input(460, 0, false), true);
    step(result_input(461, 256, false), true);
    in = result_input(462, 3, true);
    for (unsigned r = 0; r < 8; ++r) {
        e = step(in, true);
        CHECK(e.beat_written && !e.result_accepted);
    }
    e = step(in, true);
    CHECK(!e.beat_written && q.row == 0 && q.count == 1);
    // result_valid=0 must ignore even invalid metadata.
    in.result_valid = false;
    CHECK(step(in, true).beat_written);
    drain();

    phase = 5; // Long stall on LAST row, then full/partial/active reset.
    reset_model();
    step(result_input(500, UINT64_C(0x9000), false), true);
    memset(&in, 0, sizeof in);
    in.write_ready = true;
    for (unsigned r = 0; r < 7; ++r) step(in, true);
    in.write_ready = false;
    for (unsigned t = 0; t < 40; ++t) {
        e = step(in, true);
        CHECK(!e.tile_done && q.row == 7);
    }
    CHECK(step(result_input(501, UINT64_C(0xa000), false), true).result_accepted);
    CHECK(q.count == 2);
    in = result_input(502, UINT64_C(0xb000), true);
    step(in, false); // Neither input nor pending last write survives reset.
    CHECK(q.count == 0 && q.row == 0 && q.head == 0);
    memset(&in, 0, sizeof in);
    in.write_ready = true;
    step(in, true);
    step(result_input(503, UINT64_C(0xc000), true), true);
    for (unsigned r = 0; r < 3; ++r) step(in, true);
    step(in, false); // Reset after some rows have already committed.
    step(in, true);
    step(result_input(504, UINT64_C(0xd000), true), true);
    drain();
}

static void random_test(void)
{
    enum { N = 512 };
    unsigned sent = 0, beats = 0, local_cycles = 0;
    bool pending = false;
    MsuInputs in = {0};
    phase = 6;
    rng = UINT32_C(0xa5c31274);
    reset_model();
    for (; local_cycles < 200000 && beats < N*8u; ++local_cycles) {
        MsuEvents e;
        if (!pending && sent < N && (random32() >> 24) < 205) {
            uint64_t addr = ((uint64_t)(random32() & UINT32_C(0x7fffffff)) << 32) |
                            (random32() & UINT32_C(0xffffff00));
            in = result_input(UINT32_C(0x80000000) + sent, addr, false);
            pending = true;
        }
        in.result_valid = pending;
        in.write_ready = (random32() >> 24) < 175 &&
            !(local_cycles >= 20 && local_cycles < 180) &&
            local_cycles%211u >= 25u;
        e = step(in, true);
        if (e.result_accepted) { ++sent; pending = false; }
        beats += e.beat_written;
    }
    CHECK(sent == N && beats == N*8u && q.count == 0);
    fprintf(stderr, "random traffic: results=%u beats=%u cycles=%u\n", sent, beats, local_cycles);
    drain();
}

int main(void)
{
    msu_reset(&q);
    original_120_test();
    directed_tests();
    random_test();
    CHECK(simultaneous >= 33 && faults >= 40 && full_last > 0 && full_bad > 0);
    CHECK(max_count == 2 && head_wraps > 100 && resets >= 8);
    fprintf(stderr,
        "C VECTOR PASS: cycles=%u accepted=%u beats=%u done=%u simultaneous=%u "
        "faults=%u resets=%u stalls=%u full=%u full_last=%u full_bad=%u wraps=%u max_count=%u\n",
        cycle, accepted, written, completed, simultaneous, faults, resets, stalled,
        full, full_last, full_bad, head_wraps, max_count);
    return 0;
}
